css:
#tongsci2-1-1-1-1-cover .frame { flex-direction: row; gap: 72px; }
#tongsci2-1-1-1-1-cover .col-text { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 28px; }
#tongsci2-1-1-1-1-cover h1 { font-size: 112px; }
#tongsci2-1-1-1-1-cover .hero-pen { font-size: 56px; transform: rotate(-1.2deg); transform-origin: left center; margin-top: -6px; }
#tongsci2-1-1-1-1-cover .footer { left: 1100px; right: 300px; }
#tongsci2-1-1-1-1-cover .lesson-chip {
  align-self: flex-start; display: inline-flex; gap: 14px; align-items: baseline;
  border: 2px solid var(--ink); border-radius: 999px; padding: 6px 22px; font-size: 26px; font-weight: 600;
}
#tongsci2-1-1-1-1-cover .lesson-chip span { font-family: var(--f-mono); font-size: 22px; color: var(--ink-2); font-weight: 500; }
#tongsci2-1-1-1-1-cover .goals { display: flex; flex-direction: column; gap: 18px; max-width: 980px; }
#tongsci2-1-1-1-1-cover .goals-label { font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--ink-2); }
#tongsci2-1-1-1-1-cover .goal { display: grid; grid-template-columns: 52px 1fr; gap: 6px; font-size: 30px; line-height: 1.42; }
#tongsci2-1-1-1-1-cover .goal .no { font-family: var(--f-display); font-weight: 700; color: var(--ink-2); }
#tongsci2-1-1-1-1-cover .today {
  margin-top: 6px; padding: 20px 28px; background: var(--paper-2); border: 2px solid var(--ink);
  border-radius: 6px; box-shadow: 6px 6px 0 var(--ink); font-size: 32px; line-height: 1.45;
}
#tongsci2-1-1-1-1-cover .today .tag { display: block; font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--accent); margin-bottom: 6px; }
#tongsci2-1-1-1-1-cover .col-fig { flex: 0 0 700px; display: flex; flex-direction: column; gap: 14px; padding-top: 24px; }
#tongsci2-1-1-1-1-cover .fig-caption .cap { font-size: 21px; line-height: 1.4; }
#tongsci2-1-1-1-1-cover .share-card { padding: 60px 30px 26px; display: flex; flex-direction: column; gap: 18px; }
#tongsci2-1-1-1-1-cover .share-card h3 { margin: 0; font: 700 34px/1.3 var(--f-display); color: var(--ink); text-wrap: balance; }

js:
/* tongsci2.1-1-1.1.cover */
(function () {
  'use strict';
  const { part } = window.Deck;
  const single = (btns) => btns.forEach((b) => b.addEventListener('click', () => {
    const on = b.getAttribute('aria-pressed') !== 'true';
    btns.forEach((x) => x.setAttribute('aria-pressed', String(on && x === b)));
  }));

  // 1. 표지: 손전등으로 발자국 찾기(①) + 예측(②, 한 번 넘기면 답과 풀이)
  part('tongsci2-1-1-1-1-cover', (root) => {
    const lt = window.LtRake.mount(root);
    const btns = [...root.querySelectorAll('.share-opts button')], ans = root.querySelector('.cov-ans');
    single(btns);
    let shown = false;
    const steps = () => {
      const found = root.classList.contains('lt-found'), picked = btns.some((b) => b.getAttribute('aria-pressed') === 'true');
      window.L1.steps(root, !found ? 1 : !picked && !shown ? 2 : 0, [found ? 1 : 0, picked || shown ? 2 : 0]);
    };
    new MutationObserver(steps).observe(root, { attributes: true, attributeFilter: ['class'] });
    btns.forEach((b) => b.addEventListener('click', () => { steps(); if (shown) answer(true); }));
    function answer(on) {
      shown = on;
      root.querySelector('#pr-life').classList.toggle('answer', on);
      const pick = btns.find((b) => b.getAttribute('aria-pressed') === 'true');
      ans.className = 'u-pres cov-ans' + (on && pick ? (pick.id === 'pr-life' ? ' yes' : ' no') : '');
      ans.textContent = !on ? '' : !pick || pick.id === 'pr-life'
        ? '발자국도 화석이다. 화석을 보면 어떤 생물이 언제, 어떤 곳에서 살았는지 알 수 있다.'
        : '비가 만든 무늬라면 같은 세 발가락 모양이 일정한 간격으로 이어지지 않는다. 이것은 공룡 발자국 화석이다.';
      steps();
    }
    steps();
    return {
      setActive: lt.setActive, fit: lt.fit,
      fragment(f, on) { if (f.dataset.anim === 'lt') answer(on); },
      sync(slide) { const f = slide.querySelector('[data-anim="lt"]'); answer(!!f && f.classList.contains('visible')); },
    };
  });
  // 체험 장: 설명 장에서 배운 것을 조작으로 확인한다(해 볼 일 ①②③ → 알게 된 것)
})();
